public class Main {
 static class Fast {byte[] b=new byte[65536];int p,l;int read()throws Exception{if(p==l){l=System.in.read(b);p=0;if(l<0)return -1;}return b[p++];}int next()throws Exception{int c;do{c=read();}while(c<=32&&c!=-1);int x=0;while(c>32){x=x*10+c-48;c=read();}return x;}}
 public static void main(String[] args)throws Exception{Fast in=new Fast();int t=in.next();StringBuilder out=new StringBuilder();while(t-->0){int n=in.next(),size=0,parity=0;int[] values=new int[32],next=new int[32];long[] zero=new long[32],one=new long[32],nz=new long[32],no=new long[32];long answer=0;for(int i=0;i<n;i++){int a=in.next(),length=1;next[0]=a;nz[0]=parity==0?1:0;no[0]=parity==1?1:0;for(int j=0;j<size;j++){int v=values[j]&a;if(next[length-1]==v){nz[length-1]+=zero[j];no[length-1]+=one[j];}else{next[length]=v;nz[length]=zero[j];no[length]=one[j];length++;}}parity^=Integer.bitCount(a)&1;for(int j=0;j<length;j++)if((Integer.bitCount(next[j])&1)!=0)answer+=parity==0?nz[j]:no[j];int[] vi=values;values=next;next=vi;long[] temp=zero;zero=nz;nz=temp;temp=one;one=no;no=temp;size=length;}out.append(answer).append('\n');}System.out.print(out);}
}